migrations.sql:
CREATE TABLE IF NOT EXISTS learner_profiles (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE,
  display_name TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  UNIQUE (user_id, id)
);
CREATE TABLE IF NOT EXISTS learner_preferences (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE,
  source_language TEXT, target_language TEXT, region TEXT, timezone TEXT,
  reminders_enabled INTEGER NOT NULL DEFAULT 0 CHECK (reminders_enabled IN (0, 1)),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES learner_profiles (user_id),
  UNIQUE (user_id, id)
);
CREATE TABLE IF NOT EXISTS courses (
  id TEXT PRIMARY KEY, source_language TEXT NOT NULL, target_language TEXT NOT NULL,
  title TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS course_versions (
  id TEXT PRIMARY KEY, course_id TEXT NOT NULL, content_version INTEGER NOT NULL CHECK (content_version >= 0),
  package_version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'review', 'approved', 'published', 'retired')),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  UNIQUE (course_id, content_version), UNIQUE (course_id, id),
  FOREIGN KEY (course_id) REFERENCES courses (id)
);
CREATE TABLE IF NOT EXISTS lessons (
  id TEXT PRIMARY KEY, course_version_id TEXT NOT NULL, stable_content_id TEXT NOT NULL,
  content_version INTEGER NOT NULL CHECK (content_version >= 0),
  position INTEGER NOT NULL CHECK (position >= 0), title TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE (course_version_id, stable_content_id), UNIQUE (course_version_id, position),
  UNIQUE (course_version_id, id),
  FOREIGN KEY (course_version_id) REFERENCES course_versions (id)
);
CREATE TABLE IF NOT EXISTS exercises (
  id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL, stable_content_id TEXT NOT NULL,
  content_version INTEGER NOT NULL CHECK (content_version >= 0),
  position INTEGER NOT NULL CHECK (position >= 0), kind TEXT NOT NULL,
  evaluator_policy_version TEXT NOT NULL, created_at INTEGER NOT NULL,
  UNIQUE (lesson_id, stable_content_id), UNIQUE (lesson_id, position),
  UNIQUE (lesson_id, id), FOREIGN KEY (lesson_id) REFERENCES lessons (id)
);
CREATE TABLE IF NOT EXISTS learning_sessions (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, course_version_id TEXT NOT NULL,
  lesson_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'abandoned')),
  last_exercise_position INTEGER NOT NULL DEFAULT 0 CHECK (last_exercise_position >= 0),
  started_at INTEGER NOT NULL, completed_at INTEGER,
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  UNIQUE (user_id, id), UNIQUE (user_id, id, lesson_id),
  FOREIGN KEY (user_id) REFERENCES learner_profiles (user_id),
  FOREIGN KEY (course_version_id, lesson_id) REFERENCES lessons (course_version_id, id)
);
CREATE TABLE IF NOT EXISTS exercise_attempts (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_id TEXT NOT NULL,
  lesson_id TEXT NOT NULL, exercise_id TEXT NOT NULL,
  attempt_number INTEGER NOT NULL CHECK (attempt_number > 0),
  evaluator_policy_version TEXT NOT NULL, result_code TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE (user_id, session_id, exercise_id, attempt_number),
  FOREIGN KEY (user_id, session_id, lesson_id) REFERENCES learning_sessions (user_id, id, lesson_id),
  FOREIGN KEY (lesson_id, exercise_id) REFERENCES exercises (lesson_id, id)
);
CREATE TABLE IF NOT EXISTS learning_exposures (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_id TEXT NOT NULL,
  lesson_id TEXT NOT NULL, exercise_id TEXT NOT NULL, exposure_kind TEXT NOT NULL, created_at INTEGER NOT NULL,
  FOREIGN KEY (user_id, session_id, lesson_id) REFERENCES learning_sessions (user_id, id, lesson_id),
  FOREIGN KEY (lesson_id, exercise_id) REFERENCES exercises (lesson_id, id)
);
CREATE TABLE IF NOT EXISTS review_states (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, course_id TEXT NOT NULL,
  stable_content_id TEXT NOT NULL, source_exercise_id TEXT NOT NULL,
  due_at INTEGER, interval_days INTEGER NOT NULL DEFAULT 0 CHECK (interval_days >= 0),
  review_count INTEGER NOT NULL DEFAULT 0 CHECK (review_count >= 0),
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  UNIQUE (user_id, course_id, stable_content_id),
  FOREIGN KEY (user_id) REFERENCES learner_profiles (user_id),
  FOREIGN KEY (course_id) REFERENCES courses (id),
  FOREIGN KEY (source_exercise_id) REFERENCES exercises (id)
);
CREATE TABLE IF NOT EXISTS content_reports (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, exercise_id TEXT NOT NULL,
  category TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reviewing', 'resolved', 'dismissed')),
  detail TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  FOREIGN KEY (user_id) REFERENCES learner_profiles (user_id),
  FOREIGN KEY (exercise_id) REFERENCES exercises (id)
);
CREATE TABLE IF NOT EXISTS course_releases (
  id TEXT PRIMARY KEY, course_id TEXT NOT NULL, course_version_id TEXT NOT NULL,
  release_number INTEGER NOT NULL CHECK (release_number > 0),
  status TEXT NOT NULL CHECK (status IN ('active', 'superseded', 'retired')),
  published_by_user_id TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
  UNIQUE (course_id, release_number),
  FOREIGN KEY (course_id, course_version_id) REFERENCES course_versions (course_id, id)
);
CREATE TABLE IF NOT EXISTS audit_rows (
  id TEXT PRIMARY KEY, actor_user_id TEXT, subject_user_id TEXT,
  resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, action TEXT NOT NULL,
  detail_json TEXT, created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_course_versions_status ON course_versions (course_id, status, content_version DESC);
CREATE INDEX IF NOT EXISTS idx_lessons_order ON lessons (course_version_id, position);
CREATE INDEX IF NOT EXISTS idx_exercises_order ON exercises (lesson_id, position);
CREATE INDEX IF NOT EXISTS idx_sessions_resume ON learning_sessions (user_id, status, updated_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_attempts_history ON exercise_attempts (user_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_exposures_history ON learning_exposures (user_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_review_due ON review_states (user_id, due_at, id);
CREATE INDEX IF NOT EXISTS idx_reports_queue ON content_reports (status, created_at, id);
CREATE INDEX IF NOT EXISTS idx_reports_user ON content_reports (user_id, created_at DESC, id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_active_release ON course_releases (course_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_releases_history ON course_releases (course_id, release_number DESC);
CREATE INDEX IF NOT EXISTS idx_audit_resource ON audit_rows (resource_type, resource_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_rows (actor_user_id, created_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS course_locales (
 tag TEXT PRIMARY KEY,
 language TEXT NOT NULL CHECK (length(language) BETWEEN 2 AND 8 AND language NOT GLOB '*[^a-z]*'),
 script TEXT CHECK (script IS NULL OR (length(script)=4 AND substr(script,1,1) GLOB '[A-Z]' AND substr(script,2) NOT GLOB '*[^a-z]*')),
 region TEXT CHECK (region IS NULL OR ((length(region)=2 AND region NOT GLOB '*[^A-Z]*') OR (length(region)=3 AND region NOT GLOB '*[^0-9]*'))),
 created_at INTEGER NOT NULL,
 CHECK (tag=language || CASE WHEN script IS NULL THEN '' ELSE '-'||script END || CASE WHEN region IS NULL THEN '' ELSE '-'||region END)
);
CREATE TABLE IF NOT EXISTS course_maps (
 id TEXT PRIMARY KEY, course_id TEXT NOT NULL UNIQUE,
 source_tag TEXT NOT NULL, target_tag TEXT NOT NULL,
 created_at INTEGER NOT NULL,
 CHECK (source_tag<>target_tag),
 FOREIGN KEY (course_id) REFERENCES courses(id),
 FOREIGN KEY (source_tag) REFERENCES course_locales(tag),
 FOREIGN KEY (target_tag) REFERENCES course_locales(tag)
);
CREATE TABLE IF NOT EXISTS course_units (
 id TEXT PRIMARY KEY, course_version_id TEXT NOT NULL,
 stable_content_id TEXT NOT NULL, position INTEGER NOT NULL CHECK (position>=0),
 title TEXT NOT NULL CHECK (length(trim(title))>0), created_at INTEGER NOT NULL,
 UNIQUE(course_version_id,id), UNIQUE(course_version_id,stable_content_id), UNIQUE(course_version_id,position),
 FOREIGN KEY (course_version_id) REFERENCES course_versions(id)
);
CREATE TABLE IF NOT EXISTS course_unit_lessons (
 id TEXT PRIMARY KEY, course_version_id TEXT NOT NULL,
 unit_id TEXT NOT NULL, lesson_id TEXT NOT NULL,
 position INTEGER NOT NULL CHECK (position>=0), created_at INTEGER NOT NULL,
 UNIQUE(course_version_id,lesson_id), UNIQUE(unit_id,position),
 FOREIGN KEY (course_version_id,unit_id) REFERENCES course_units(course_version_id,id),
 FOREIGN KEY (course_version_id,lesson_id) REFERENCES lessons(course_version_id,id)
);
CREATE TABLE IF NOT EXISTS lesson_prerequisites (
 id TEXT PRIMARY KEY, course_version_id TEXT NOT NULL,
 lesson_id TEXT NOT NULL, prerequisite_lesson_id TEXT NOT NULL,
 created_at INTEGER NOT NULL, CHECK (lesson_id<>prerequisite_lesson_id),
 UNIQUE(course_version_id,lesson_id,prerequisite_lesson_id),
 FOREIGN KEY (course_version_id,lesson_id) REFERENCES lessons(course_version_id,id),
 FOREIGN KEY (course_version_id,prerequisite_lesson_id) REFERENCES lessons(course_version_id,id)
);
CREATE INDEX IF NOT EXISTS idx_course_maps_pair ON course_maps(source_tag,target_tag,course_id);
CREATE INDEX IF NOT EXISTS idx_course_units_order ON course_units(course_version_id,position,id);
CREATE INDEX IF NOT EXISTS idx_unit_lessons_order ON course_unit_lessons(unit_id,position,id);
CREATE INDEX IF NOT EXISTS idx_lesson_prerequisites ON lesson_prerequisites(course_version_id,lesson_id,prerequisite_lesson_id);
CREATE TRIGGER IF NOT EXISTS course_locale_no_update BEFORE UPDATE ON course_locales BEGIN SELECT RAISE(ABORT,'course locale is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_locale_no_delete BEFORE DELETE ON course_locales BEGIN SELECT RAISE(ABORT,'course locale is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_map_no_update BEFORE UPDATE ON course_maps BEGIN SELECT RAISE(ABORT,'course map is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_map_no_delete BEFORE DELETE ON course_maps BEGIN SELECT RAISE(ABORT,'course map is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_units_draft_insert BEFORE INSERT ON course_units
WHEN NOT EXISTS (SELECT 1 FROM course_versions WHERE id=NEW.course_version_id AND status='draft')
BEGIN SELECT RAISE(ABORT,'unit requires draft version'); END;
CREATE TRIGGER IF NOT EXISTS course_units_no_update BEFORE UPDATE ON course_units BEGIN SELECT RAISE(ABORT,'unit is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_units_no_delete BEFORE DELETE ON course_units BEGIN SELECT RAISE(ABORT,'unit is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_unit_lessons_draft_insert BEFORE INSERT ON course_unit_lessons
WHEN NOT EXISTS (SELECT 1 FROM course_versions WHERE id=NEW.course_version_id AND status='draft')
BEGIN SELECT RAISE(ABORT,'unit lesson requires draft version'); END;
CREATE TRIGGER IF NOT EXISTS course_unit_lessons_no_update BEFORE UPDATE ON course_unit_lessons BEGIN SELECT RAISE(ABORT,'unit lesson is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_unit_lessons_no_delete BEFORE DELETE ON course_unit_lessons BEGIN SELECT RAISE(ABORT,'unit lesson is immutable'); END;
CREATE TRIGGER IF NOT EXISTS lesson_prerequisites_draft_insert BEFORE INSERT ON lesson_prerequisites
WHEN NOT EXISTS (SELECT 1 FROM course_versions WHERE id=NEW.course_version_id AND status='draft')
BEGIN SELECT RAISE(ABORT,'prerequisite requires draft version'); END;
CREATE TRIGGER IF NOT EXISTS lesson_prerequisites_no_update BEFORE UPDATE ON lesson_prerequisites BEGIN SELECT RAISE(ABORT,'prerequisite is immutable'); END;
CREATE TRIGGER IF NOT EXISTS lesson_prerequisites_no_delete BEFORE DELETE ON lesson_prerequisites BEGIN SELECT RAISE(ABORT,'prerequisite is immutable'); END;
CREATE TRIGGER IF NOT EXISTS lesson_prerequisites_no_cycle BEFORE INSERT ON lesson_prerequisites
WHEN EXISTS (
 WITH RECURSIVE ancestors(id) AS (
   SELECT NEW.prerequisite_lesson_id
   UNION
   SELECT p.prerequisite_lesson_id FROM lesson_prerequisites p JOIN ancestors a ON p.lesson_id=a.id WHERE p.course_version_id=NEW.course_version_id
 ) SELECT 1 FROM ancestors WHERE id=NEW.lesson_id
)
BEGIN SELECT RAISE(ABORT,'prerequisite cycle'); END;
CREATE VIEW IF NOT EXISTS course_map_release_state AS
SELECT c.id AS course_id,
 CASE WHEN EXISTS(SELECT 1 FROM course_releases r WHERE r.course_id=c.id AND r.status='active') THEN 'published'
 WHEN EXISTS(SELECT 1 FROM course_releases r WHERE r.course_id=c.id AND r.status IN ('retired','superseded')) THEN 'deprecated'
 ELSE 'draft' END AS release_state
FROM courses c;
CREATE TRIGGER IF NOT EXISTS course_map_language_match BEFORE INSERT ON course_maps
WHEN NOT EXISTS (
 SELECT 1 FROM courses c JOIN course_locales src ON src.tag=NEW.source_tag JOIN course_locales dst ON dst.tag=NEW.target_tag
 WHERE c.id=NEW.course_id AND (lower(c.source_language)=src.language OR c.source_language=src.tag)
 AND (lower(c.target_language)=dst.language OR c.target_language=dst.tag)
)
BEGIN SELECT RAISE(ABORT,'course language mismatch'); END;
CREATE TRIGGER IF NOT EXISTS course_version_identity_immutable BEFORE UPDATE ON course_versions
WHEN NEW.id<>OLD.id OR NEW.course_id<>OLD.course_id OR NEW.content_version<>OLD.content_version OR NEW.package_version<>OLD.package_version OR NEW.created_at<>OLD.created_at
BEGIN SELECT RAISE(ABORT,'course version identity is immutable'); END;
CREATE TRIGGER IF NOT EXISTS course_version_state_transition BEFORE UPDATE OF status ON course_versions
WHEN NEW.status<>OLD.status AND NOT (
 (OLD.status='draft' AND NEW.status='review') OR
 (OLD.status='review' AND NEW.status IN ('draft','approved')) OR
 (OLD.status='approved' AND NEW.status='published') OR
 (OLD.status='published' AND NEW.status='retired')
)
BEGIN SELECT RAISE(ABORT,'invalid course version transition'); END;
CREATE TRIGGER IF NOT EXISTS course_version_no_delete BEFORE DELETE ON course_versions BEGIN SELECT RAISE(ABORT,'course version is immutable'); END;
